style.css:
@-moz-document domain("roblox.com") {
/* ---------------------------------------------------------------------
   1. Core palette + typography
   2016 Roblox ran on Arial/Helvetica, a near-white #f2f2f2 page bg,
   a white top bar, and #0099ff links/primary buttons.
--------------------------------------------------------------------- */

:root {
  --rbx16-blue: #0099ff;
  --rbx16-blue-dark: #0087e0;
  --rbx16-orange: #f9a000;
  --rbx16-green: #57bb01;
  --rbx16-bg: #f2f2f2;
  --rbx16-panel: #ffffff;
  --rbx16-border: #e3e3e3;
  --rbx16-text: #393b3d;
}

html, body {
  background-color: var(--rbx16-bg) !important;
  color: var(--rbx16-text) !important;
}

body, body * {
  font-family: Arial, Helvetica, "Segoe UI", sans-serif !important;
  -webkit-font-smoothing: auto !important;
}

/* Force light mode even if the dark theme is active — 2016 had one theme */
html[class*="dark"], body[class*="dark"], [data-theme="dark"],
[class*="dark-theme"] {
  background-color: var(--rbx16-bg) !important;
  color: var(--rbx16-text) !important;
}

a, a:visited {
  color: var(--rbx16-blue) !important;
  text-decoration: none;
}
a:hover { text-decoration: underline; }

/* Flatten every rounded "app card" corner back to the old boxy look */
button, .btn, [class*="button"], [class*="card"], [class*="Card"],
[class*="modal"], [class*="tile"], [class*="Tile"], input, textarea,
[class*="chip"], [class*="pill"] {
  border-radius: 2px !important;
  box-shadow: none !important;
}

/* Primary buttons -> classic blue, no gradients */
.btn-primary, .btn-primary-md, .btn-primary-lg,
button[class*="primary"], [class*="btn-primary"], [class*="Primary"] {
  background: var(--rbx16-blue) !important;
  background-image: none !important;
  border-color: var(--rbx16-blue-dark) !important;
  color: #fff !important;
}

/* ---------------------------------------------------------------------
   2. Top navigation bar (legacy markup, still served on several pages)
--------------------------------------------------------------------- */

.rbx-header, #header, header[class*="header"], header[class*="Header"] {
  background-color: var(--rbx16-panel) !important;
  background-image: none !important;
  border-bottom: 1px solid var(--rbx16-border) !important;
  box-shadow: none !important;
  height: 46px !important;
  min-height: 46px !important;
}

.rbx-navbar-header, .navbar-header, [class*="navbar-header"] {
  height: 46px !important;
}

.navbar-brand, a[class*="navbar-brand"], a[class*="logo"] {
  height: 46px !important;
  filter: none !important;
}

.rbx-navbar .nav-menu-title, [class*="nav-menu-title"],
nav[class*="nav"] a[class*="item"] {
  color: var(--rbx16-text) !important;
  font-weight: bold !important;
  text-transform: none !important;
  font-size: 13px !important;
}

/* Robux balance -> flat orange coin, no purple/gradient icon */
[class*="robux-icon"], [class*="icon-robux"], span[class*="robux"],
[class*="currency"] svg, [class*="currency"] path {
  color: var(--rbx16-orange) !important;
  fill: var(--rbx16-orange) !important;
  filter: none !important;
}

/* ---------------------------------------------------------------------
   3. Left icon rail / sidebar
   2016 had no persistent left rail — collapse it back to a plain
   horizontal top nav and let content use the full width.
--------------------------------------------------------------------- */

nav[class*="left-nav"], div[id*="left-nav"],
[class*="sidebar"][class*="nav"], [class*="LeftNav"] {
  display: none !important;
}

.container-main, main[class*="container"], [class*="page-content"] {
  margin-left: 0 !important;
  max-width: 1000px !important;
  margin-right: auto !important;
}

/* ---------------------------------------------------------------------
   4. Homepage game grid
   Back to square, bordered thumbnails with a plain title strip,
   instead of floating rounded cards with heavy shadows.
--------------------------------------------------------------------- */

.game-home-page-container, [class*="game-home-page"],
[class*="HomePage"] {
  background-color: var(--rbx16-bg) !important;
}

.container-header, [class*="container-header"], [class*="sectionHeader"] {
  background: none !important;
  border-bottom: 1px solid var(--rbx16-border) !important;
  font-weight: bold !important;
  text-transform: uppercase !important;
  font-size: 13px !important;
  color: #6d6d6d !important;
}

.game-card, [class*="game-card"], [class*="GameCard"] {
  border-radius: 0 !important;
  border: 1px solid var(--rbx16-border) !important;
  box-shadow: none !important;
  background-color: var(--rbx16-panel) !important;
}

.game-card img, [class*="game-card"] img, [class*="thumbnail"] img {
  border-radius: 0 !important;
}

.game-card-name, [class*="game-card-name"], [class*="gameCardName"],
[class*="GameName"] {
  font-weight: normal !important;
  font-size: 13px !important;
  color: var(--rbx16-blue) !important;
}

/* ---------------------------------------------------------------------
   5. Search bar
--------------------------------------------------------------------- */

.rbx-navbar-search, [class*="navbar-search"], input[class*="search"],
[class*="SearchBar"] {
  border-radius: 2px !important;
  border: 1px solid #cfcfcf !important;
  box-shadow: none !important;
  background-color: #fff !important;
  background-image: none !important;
}
}
